F_ISSUE_TOTALUNIT F_ISSUE_TOTALUNIT, F_INFO_MANAGEMENTFEERATIO F_INFO_MANAGEMENTFEERATIO, F_INFO_CUSTODIANFEERATIO F_INFO_CUSTODIANFEERATIO, F_INFO_BENCHMARK F_INFO_BENCHMARK, F_INFO_EXCHMARKET F_INFO_EXCHMARKET, to_date(F_INFO_ISSUEDATE, 'yyyy-mm-dd') F_INFO_ISSUEDATE, F_INFO_TYPE F_INFO_TYPE, F_INFO_TYPE2 F_INFO_TYPE2, F_INFO_CORP_FUNDMANAGEMENTID F_INFO_CORP_FUNDMANAGEMENTID, F_INFO_CUSTODIANBANKID F_INFO_CUSTODIANBANKID FROM INTERF_CMFUNDDESCRIP
