SELECT t.ASSET_COOD assetcode, t.ASSET_NAME assetname, t.COMPANY_NAME companyname, t.COMPANY_CODE companycode, case when t.TRADE_PLACE = '深圳证券交易所' then '04' when t.TRADE_PLACE = '上海证券交易所' then '03' end tradeplace, case when t.LISTING_BOARD = '主板' then 'BD01' when t.LISTING_BOARD = '中小企业板' then 'BD02' when t.LISTING_BOARD = '科创板' then 'BD03' when t.LISTING_BOARD = '创业板' then 'BD04' end listingboard, t.LISTING_DATE listingdate, t.DELISTING_DATE delistingdate, case when t.IS_HORS_EXPRESS = '沪股通' then '01' when t.IS_HORS_EXPRESS = '深股通' then '02' when t.IS_HORS_EXPRESS = '否' then '03' end ishorsexpress, case when t.IS_MARGIN_TRADING = '是' then 'Y' when t.IS_MARGIN_TRADING = '否' then 'N' end ismargintrading, CCY ccy, t.TRADE_CALENDER tradecalender, case when t.STOCK_TYPE = '普通股' then '01' when t.STOCK_TYPE = '优先股' then '02' when t.STOCK_TYPE = '其他' then '99' end stocktype, t.INDUSTRY_S industrys, t.ENTERPRISE_TYPE3 enterprisetype3, t.ENTERPRISE_TYPE1 enterprisetype1, t.ENTERPRISE_TYPE2 enterprisetype2, t.CREATE_USER createuser, t.CREATE_DEPT createdept, t.UPDATE_USER updateuser FROM INTERF_STOCK_INFO t
and (t.ASSET_NAME in
null) OR F_INFO_NAME IN (
#{obj}
)
